  useEffect(() => {
    if (status === 'processing') {
      const timer = setTimeout(() => {
        setStatus('success');
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [status]);

  const handleSimulateDetection = () => {
    if (status === 'scanning') {
