                  className="block w-full pl-11 pr-4 py-3.5 border-none rounded-2xl bg-gray-50 text-gray-900 text-sm focus:ring-2 focus:ring-emerald-500/20 focus:bg-white transition-all shadow-inner disabled:opacity-50"
