### Script SQL para o Supabase

Copie e cole este código no **SQL Editor** do seu projeto no Supabase para criar a infraestrutura necessária:

```sql
-- 1. Criar tabela de perfis para estender auth.users
CREATE TABLE IF NOT EXISTS profiles (
  id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  nome TEXT,
  telefone TEXT,
  perfil TEXT DEFAULT 'USUARIO' CHECK (perfil IN ('ADMIN', 'USUARIO')),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 2. Criar tabela de mercados
CREATE TABLE IF NOT EXISTS markets (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  ativo BOOLEAN DEFAULT true,
  data_criacao TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 3. Criar tabela de produtos
CREATE TABLE IF NOT EXISTS products (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  categoria TEXT,
  ativo BOOLEAN DEFAULT true,
  imagem_url TEXT,
  data_criacao TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 4. Criar tabela de preços
CREATE TABLE IF NOT EXISTS prices (
  id TEXT PRIMARY KEY,
  produto_id TEXT REFERENCES products(id) ON DELETE CASCADE,
  mercado_id TEXT REFERENCES markets(id) ON DELETE CASCADE,
  valor NUMERIC(10,2) NOT NULL,
  data_atualizacao TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
  ativo BOOLEAN DEFAULT true
);

-- 5. Trigger para criar perfil automaticamente no SignUp
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger AS $$
BEGIN
  INSERT INTO public.profiles (id, nome, telefone, perfil)
  VALUES (
    new.id, 
    new.raw_user_meta_data->>'nome', 
    new.raw_user_meta_data->>'telefone',
    'USUARIO'
  );
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

-- 6. Configurar Políticas de Segurança (RLS)
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE markets ENABLE ROW LEVEL SECURITY;
ALTER TABLE prices ENABLE ROW LEVEL SECURITY;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

-- Visualização pública para todos
CREATE POLICY "Produtos visíveis para todos" ON products FOR SELECT USING (true);
CREATE POLICY "Mercados visíveis para todos" ON markets FOR SELECT USING (true);
CREATE POLICY "Preços visíveis para todos" ON prices FOR SELECT USING (true);

-- Controle total apenas para ADMIN (via Perfil)
