                  <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 bg-gray-50 rounded-full p-2">
                    <X size={24} />
                  </button>
                </div>

                <form id="marketForm" onSubmit={handleSave} className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome do Estabelecimento</label>
                    <input 
                      type="text" 
                      required
                      value={name} 
                      onChange={e => setName(e.target.value)}
                      className="block w-full border-none bg-gray-50 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-2 focus:ring-emerald-500/20 focus:bg-white transition-all outline-none" 
                      placeholder="Ex: Farmácia do Bairro"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Latitude</label>
                        <input 
                            type="text" 
                            value={latitude} 
                            onChange={e => setLatitude(e.target.value)}
                            className="block w-full border-none bg-gray-50 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-2 focus:ring-emerald-500/20 focus:bg-white transition-all outline-none" 
                            placeholder="-23.5505"
                        />
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Longitude</label>
                        <input 
                            type="text" 
                            value={longitude} 
                            onChange={e => setLongitude(e.target.value)}
                            className="block w-full border-none bg-gray-50 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-2 focus:ring-emerald-500/20 focus:bg-white transition-all outline-none" 
                            placeholder="-46.6333"
                        />
                    </div>
                  </div>

                  <button 
                    type="button"
                    onClick={captureCurrentLocation}
                    disabled={isCapturing}
                    className="w-full flex items-center justify-center gap-2 py-4 px-4 bg-emerald-50 text-emerald-700 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-emerald-100 transition-all border-2 border-dashed border-emerald-200"
                  >
                    {isCapturing ? (
                        <>Capturando...</>
                    ) : (
                        <><Crosshair size={18} /> Usar minha localização atual</>
                    )}
                  </button>
                </form>
              </div>

              <div className="bg-gray-50 p-6 flex gap-3">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-4 bg-white border border-gray-200 rounded-2xl text-xs font-black text-gray-400 uppercase tracking-widest hover:bg-gray-100 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  form="marketForm"
                  className="flex-1 py-4 bg-emerald-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 shadow-xl shadow-emerald-100 transition-all active:scale-95"
                >
                  Salvar Dados
                </button>
              </div>
            </div>
          </div>
      )}
    </div>
  );
};

