/**
 * Calcula a distância entre dois pontos geográficos em KM usando a fórmula de Haversine
 */
export const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371; // Raio da Terra em km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
    Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

/**
 * Busca apenas o nome da cidade usando a API do OpenStreetMap (Nominatim)
 */
export const getAddressFromCoords = async (lat: number, lon: number): Promise<string> => {
  try {
    const response = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lon}`,
      {
        headers: {
          'Accept-Language': 'pt-BR'
        }
      }
    );
    const data = await response.json();

    // Prioriza campos de cidade conforme a hierarquia do Nominatim
    const city = data.address?.city || 
                 data.address?.town || 
                 data.address?.village || 
                 data.address?.municipality ||
                 data.address?.city_district;

    const state = data.address?.state;
    const stateCode = state ? `, ${state}` : '';

    if (city) return city;

    return "Localização Identificada";
  } catch (err) {
    console.error("Erro ao buscar endereço:", err);
    return "São Paulo"; // Fallback simplificado
  }
};

