import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, MapPin, Share2, AlertCircle, Loader2 } from 'lucide-react';
import { DB } from '../services/db';
import { Product, PriceComparison } from '../types';

export const ProductDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [product, setProduct] = useState<Product | null>(null);
  const [comparisons, setComparisons] = useState<PriceComparison[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      if (!id) return;
      try {
        setLoading(true);
        // Busca apenas produtos ativos. Se estiver inativo, não retorna na lista filtrada.
        const products = await DB.getProducts(undefined, undefined, true);
        const foundProduct = products.find(p => p.id === id);
        setProduct(foundProduct || null);

        if (foundProduct) {
          const prices = await DB.getPrices(id);
          const markets = await DB.getMarkets();

          if (prices.length > 0) {
            const minPrice = Math.min(...prices.map(p => p.valor));
            const comps: PriceComparison[] = prices.map(price => {
              const market = markets.find(m => m.id === price.mercado_id);
              return {
                marketName: market ? market.nome : 'Mercado Desconhecido',
                price: price.valor,
                lastUpdate: price.data_atualizacao,
                isLowest: price.valor === minPrice && minPrice > 0
              };
            }).sort((a, b) => a.price - b.price);
            setComparisons(comps);
          }
        }
      } catch (err) {
        console.error("Erro ao carregar detalhes:", err);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, [id]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <Loader2 className="animate-spin text-emerald-500" size={32} />
      </div>
    );
  }

  if (!product) return (
    <div className="p-10 text-center">
       <p className="text-gray-500">Produto não encontrado ou indisponível.</p>
       <button onClick={() => navigate('/')} className="mt-4 text-emerald-600 font-bold">Voltar</button>
    </div>
  );

  const bestPrice = comparisons.find(c => c.isLowest)?.price;
  const worstPrice = comparisons.length > 1 ? comparisons[comparisons.length - 1].price : bestPrice;
  const savings = bestPrice && worstPrice ? worstPrice - bestPrice : 0;

  return (
    <div className="bg-white min-h-screen pb-20">
      <div className="relative h-72 bg-gray-100">
        <img 
          src={product.imagem_url || "https://picsum.photos/400/400"} 
          alt={product.nome}
          className="w-full h-full object-cover"
        />
        <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start bg-gradient-to-b from-black/30 to-transparent">
            <button onClick={() => navigate(-1)} className="w-10 h-10 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white">
                <ArrowLeft size={20} />
            </button>
            <button className="w-10 h-10 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white">
                <Share2 size={20} />
            </button>
        </div>
      </div>

      <div className="-mt-8 relative bg-white rounded-t-[2rem] px-6 pt-8 pb-4 shadow-[0_-4px_20px_rgba(0,0,0,0.05)]">
         <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6"></div>

         <div className="mb-6">
            <span className="inline-block px-3 py-1 bg-emerald-50 text-emerald-700 text-xs font-bold rounded-full uppercase tracking-wide mb-2">
                {product.categoria}
            </span>
            <h1 className="text-2xl font-bold text-gray-900 leading-tight">{product.nome}</h1>

            {savings > 0 && (
                <div className="mt-3 flex items-center gap-2 text-sm text-gray-500">
                    <span className="bg-orange-100 text-orange-700 px-2 py-0.5 rounded text-xs font-bold">Economia</span>
                    <span>Poupe até <b>R$ {savings.toFixed(2).replace('.', ',')}</b> neste item</span>
                </div>
            )}
         </div>

         <div className="space-y-6">
            <h3 className="font-bold text-gray-800 text-lg">Comparativo</h3>

            {comparisons.length === 0 ? (
                <div className="bg-gray-50 rounded-xl p-6 text-center border border-dashed border-gray-200">
                    <AlertCircle className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                    <p className="text-gray-500 text-sm">Sem preços cadastrados no momento.</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {comparisons.map((comp, idx) => (
                        <div 
                            key={idx}
                            className={`flex items-center justify-between p-4 rounded-xl border transition-all ${
                                comp.isLowest 
                                ? 'bg-emerald-50/50 border-emerald-500/30 shadow-sm relative overflow-hidden' 
                                : 'bg-white border-gray-100'
                            }`}
                        >
                            {comp.isLowest && (
                                <div className="absolute left-0 top-0 bottom-0 w-1 bg-emerald-500"></div>
                            )}

                            <div className="flex items-center gap-3">
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${comp.isLowest ? 'bg-emerald-100 text-emerald-600' : 'bg-gray-100 text-gray-400'}`}>
                                    <MapPin size={18} />
                                </div>
                                <div>
                                    <p className="font-semibold text-gray-800 text-sm">{comp.marketName}</p>
                                    <p className="text-[10px] text-gray-400">
                                        {new Date(comp.lastUpdate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                            </div>

                            <div className="text-right">
                                {comp.isLowest && <p className="text-[10px] font-bold text-emerald-600 uppercase mb-0.5">Melhor Preço</p>}
                                <p className={`font-bold text-lg ${comp.isLowest ? 'text-emerald-700' : 'text-gray-600'}`}>
                                    R$ {comp.price.toFixed(2).replace('.', ',')}
                                </p>
                            </div>
                        </div>
                    ))}
                </div>
            )}
         </div>
      </div>
    </div>
  );
};

import { Market, Product, Price, ScanSubmission } from '../types';
import { supabase } from './supabase';

export const DB = {
  getMarkets: async (): Promise<Market[]> => {
    const { data, error } = await supabase
      .from('markets')
      .select('*')
      .eq('ativo', true)
      .order('nome');

    if (error) throw error;
    return data || [];
  },

  getProducts: async (searchTerm?: string, category?: string, onlyActive: boolean = false): Promise<Product[]> => {
    let query = supabase.from('products').select('*');

    if (onlyActive) {
      query = query.eq('ativo', true);
    }

    if (searchTerm) {
      query = query.ilike('nome', `%${searchTerm}%`);
    }

    if (category && category !== 'Todas') {
      query = query.eq('categoria', category);
    }

    const { data, error } = await query.order('nome');
    if (error) throw error;
    return data || [];
  },

  getPrices: async (productId?: string, marketId?: string): Promise<Price[]> => {
    let query = supabase.from('prices').select('*').eq('ativo', true);

    if (productId) {
      query = query.eq('produto_id', productId);
    }

    if (marketId) {
      query = query.eq('mercado_id', marketId);
    }

    const { data, error } = await query.order('data_atualizacao', { ascending: false });
    if (error) throw error;
    return data || [];
  },

  getUsersCount: async (): Promise<number> => {
    const { count, error } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true });

    if (error) return 0;
    return count || 0;
  },

  saveMarket: async (market: Market) => {
    const { error } = await supabase.from('markets').upsert(market);
    if (error) throw error;
  },

  deleteMarket: async (id: string) => {
    const { error } = await supabase.from('markets').delete().eq('id', id);
    if (error) throw error;
  },

  saveProduct: async (product: Product) => {
    const { error } = await supabase.from('products').upsert(product);
    if (error) throw error;
  },

  deleteProduct: async (id: string) => {
    const { error } = await supabase.from('prices').delete().eq('produto_id', id);
    const { error: prodError } = await supabase.from('products').delete().eq('id', id);
    if (prodError) throw prodError;
  },

  deletePricesFromProduct: async (productId: string) => {
    const { error } = await supabase.from('prices').delete().eq('produto_id', productId);
    if (error) throw error;
  },

  savePrice: async (price: Price) => {
    // Verifica se já existe um preço para este produto neste mercado
    const { data: existingPrices, error: fetchError } = await supabase
      .from('prices')
      .select('id')
      .eq('produto_id', price.produto_id)
      .eq('mercado_id', price.mercado_id);

    if (fetchError) throw fetchError;

    if (existingPrices && existingPrices.length > 0) {
      // Se já existe, atualizamos o primeiro registro encontrado
      const idToUpdate = existingPrices[0].id;

      const { error: updateError } = await supabase
        .from('prices')
        .update({
          valor: price.valor,
          data_atualizacao: price.data_atualizacao,
          ativo: price.ativo
        })
        .eq('id', idToUpdate);

      if (updateError) throw updateError;

      // Limpeza: Se houver duplicatas (registros extras), excluímos para manter apenas um
      if (existingPrices.length > 1) {
        const idsToDelete = existingPrices.slice(1).map(p => p.id);
        await supabase.from('prices').delete().in('id', idsToDelete);
      }
    } else {
      // Se não existe, inserimos um novo
      const { error } = await supabase.from('prices').insert(price);
      if (error) throw error;
    }
  },

  getLowestPriceForProduct: async (productId: string): Promise<number | null> => {
    const { data, error } = await supabase
      .from('prices')
      .select('valor')
      .eq('produto_id', productId)
      .eq('ativo', true)
      .order('valor', { ascending: true })
      .limit(1)
      .single();

    if (error && error.code !== 'PGRST116') throw error;
    return data ? data.valor : null;
  },

  // --- Scan Methods ---

  saveScan: async (content: string, userId?: string) => {
    try {
      const payload: any = {
        content: content,
        status: 'pending'
      };

      if (userId) payload.user_id = userId;

      const { data, error } = await supabase
        .from('scans')
        .insert([payload])
        .select();

      if (error) {
        console.error("Erro Supabase ao salvar scan:", error);
        throw error;
      }

      console.log("Scan salvo com sucesso:", data);
      return true;
    } catch (err) {
      console.error("Falha ao salvar scan:", err);
      throw err;
    }
  },

  getPendingScans: async (): Promise<ScanSubmission[]> => {
    try {
      const { data, error } = await supabase
        .from('scans')
        .select(`
          *,
          profiles:user_id ( nome )
        `)
        .eq('status', 'pending')
        .order('created_at', { ascending: false });

      if (error) {
        if (error.code === 'PGRST204' || error.code === '42P01') {
           console.error("Tabela 'scans' não existe. Execute o SQL de criação.");
           return [];
        }
        throw error;
      }

      return (data || []).map((item: any) => ({
        ...item,
        user_nome: item.profiles?.nome || 'Usuário Anônimo'
      }));
    } catch (err) {
      console.error("Erro ao buscar scans pendentes:", err);
      return [];
    }
  },

  markScanAsProcessed: async (id: string) => {
    const { error } = await supabase
      .from('scans')
      .update({ status: 'processed' })
      .eq('id', id);
    if (error) throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { ArrowLeft, MapPin, Store, Loader2, Tag, Calendar, ShoppingBag } from 'lucide-react';
import { DB } from '../services/db';
import { Market, Product, Price } from '../types';

export const MarketDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [market, setMarket] = useState<Market | null>(null);
  const [loading, setLoading] = useState(true);
  const [categories, setCategories] = useState<Record<string, Array<Product & { currentPrice: number, lastUpdate: string }>>>({});

  useEffect(() => {
    const loadData = async () => {
      if (!id) return;
      try {
        setLoading(true);
        // Busca mercados e seleciona o atual
        const markets = await DB.getMarkets();
        const foundMarket = markets.find(m => m.id === id);
        setMarket(foundMarket || null);

        if (foundMarket) {
          // Busca preços específicos deste mercado
          const prices = await DB.getPrices(undefined, id);

          // Busca produtos ativos para cruzar informações
          const products = await DB.getProducts(undefined, undefined, true);

          // Processamento dos dados
          const groupedData: Record<string, Array<Product & { currentPrice: number, lastUpdate: string }>> = {};

          prices.forEach(price => {
             const product = products.find(p => p.id === price.produto_id);
             if (product) {
                 if (!groupedData[product.categoria]) {
                     groupedData[product.categoria] = [];
                 }
                 groupedData[product.categoria].push({
                     ...product,
                     currentPrice: price.valor,
                     lastUpdate: price.data_atualizacao
                 });
             }
          });

          setCategories(groupedData);
        }
      } catch (err) {
        console.error("Erro ao carregar detalhes do mercado:", err);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [id]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <Loader2 className="animate-spin text-emerald-500" size={32} />
      </div>
    );
  }

  if (!market) {
    return (
      <div className="p-10 text-center flex flex-col items-center">
         <Store size={48} className="text-gray-300 mb-4" />
         <p className="text-gray-500 font-bold">Mercado não encontrado.</p>
         <button onClick={() => navigate(-1)} className="mt-6 text-emerald-600 font-bold bg-emerald-50 px-6 py-3 rounded-2xl">Voltar</button>
      </div>
    );
  }

  const categoryNames = Object.keys(categories).sort();

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
       {/* Header */}
       <div className="bg-white pb-6 pt-4 px-4 sticky top-0 z-30 shadow-sm rounded-b-[2rem]">
          <div className="flex items-center gap-4 mb-4">
             <button onClick={() => navigate(-1)} className="w-10 h-10 bg-gray-50 rounded-full flex items-center justify-center text-gray-600 hover:bg-gray-100 transition-colors">
                <ArrowLeft size={20} />
             </button>
             <h1 className="text-lg font-black text-gray-900 truncate flex-1">{market.nome}</h1>
          </div>

          <div className="flex items-start gap-3 px-2">
             <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center flex-shrink-0">
                <Store size={24} />
             </div>
             <div>
                <div className="flex items-center gap-1 text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">
                    <MapPin size={12} />
                    <span>Localização</span>
                </div>
                <p className="text-sm font-medium text-gray-700">
                    {market.latitude && market.longitude 
                        ? `${market.latitude.toFixed(4)}, ${market.longitude.toFixed(4)}` 
                        : 'Endereço não cadastrado'}
                </p>
                <div className="mt-3 flex gap-2">
                    <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-2 py-1 rounded-md uppercase tracking-wide">
                        {Object.values(categories).flat().length} Ofertas
                    </span>
                    <span className="bg-orange-50 text-orange-600 text-[10px] font-black px-2 py-1 rounded-md uppercase tracking-wide">
                        {categoryNames.length} Categorias
                    </span>
                </div>
             </div>
          </div>
       </div>

       {/* Conteúdo */}
       <div className="p-4 max-w-7xl mx-auto space-y-8 mt-4">
          {categoryNames.length === 0 ? (
              <div className="text-center py-20 opacity-50">
                  <ShoppingBag size={48} className="mx-auto mb-4 text-gray-300" />
                  <p className="text-gray-500 font-bold">Nenhum produto cadastrado neste mercado.</p>
              </div>
          ) : (
              categoryNames.map(category => (
                  <div key={category} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                      <div className="flex items-center gap-2 mb-4 ml-1">
                          <Tag size={16} className="text-emerald-500" />
                          <h2 className="font-black text-gray-700 uppercase tracking-widest text-xs">{category}</h2>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                          {categories[category].map(product => (
                              <Link 
                                key={product.id} 
                                to={`/product/${product.id}`}
                                className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4 active:scale-[0.99] transition-all"
                              >
                                <div className="w-16 h-16 bg-gray-50 rounded-xl flex-shrink-0 overflow-hidden">
                                    <img 
                                        src={product.imagem_url || "https://picsum.photos/100/100"} 
                                        alt={product.nome}
                                        className="w-full h-full object-cover"
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h4 className="font-bold text-gray-800 text-sm truncate">{product.nome}</h4>
                                    <div className="flex items-center gap-1 mt-1 text-[10px] text-gray-400 font-medium">
                                        <Calendar size={10} />
                                        <span>Atualizado em {new Date(product.lastUpdate).toLocaleDateString('pt-BR')}</span>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <span className="block text-[10px] text-gray-400 font-bold uppercase tracking-wider">Por apenas</span>
                                    <span className="text-lg font-black text-emerald-600">R$ {product.currentPrice.toFixed(2).replace('.', ',')}</span>
                                </div>
                              </Link>
                          ))}
                      </div>
                  </div>
              ))
          )}
       </div>
    </div>
  );
};

import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { Navbar } from './components/Navbar';
import { BottomNav } from './components/BottomNav';
import { AdminLayout } from './components/AdminLayout';
import { Home } from './pages/Home';
import { ProductDetails } from './pages/ProductDetails';
import { MarketDetails } from './pages/MarketDetails';
import { Explore } from './pages/Explore';
import { Scan } from './pages/Scan';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Profile } from './pages/Profile';
import { Dashboard } from './pages/admin/Dashboard';
import { ManageProducts } from './pages/admin/ManageProducts';
import { ManageMarkets } from './pages/admin/ManageMarkets';
import { ManagePrices } from './pages/admin/ManagePrices';

const PrivateRoute: React.FC<{ children: React.ReactElement, requireAdmin?: boolean }> = ({ children, requireAdmin = false }) => {
  const { user, isAdmin, loading } = useAuth();

  if (loading) return null; // Ou um loader global

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  if (requireAdmin && !isAdmin) {
    return <Navigate to="/" replace />;
  }

  return children;
};

const PublicLayout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  return (
    <div className="flex flex-col min-h-screen bg-slate-50">
      {user && <Navbar />}
      <main className={`flex-grow ${user ? 'pb-24 md:pb-8' : ''}`}>
        {children}
      </main>
      {user && <BottomNav />}
    </div>
  );
};

const AppContent: React.FC = () => {
  const { user, loading } = useAuth();

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <Loader2 className="animate-spin text-emerald-500" size={32} />
      </div>
    );
  }

  return (
    <Routes>
      {/* Auth Routes */}
      <Route path="/login" element={user ? <Navigate to="/" /> : <Login />} />
      <Route path="/register" element={user ? <Navigate to="/" /> : <Register />} />

      {/* Admin Routes - Use Admin Layout */}
      <Route path="/admin/dashboard" element={
        <PrivateRoute requireAdmin>
          <AdminLayout><Dashboard /></AdminLayout>
        </PrivateRoute>
      } />
      <Route path="/admin/products" element={
        <PrivateRoute requireAdmin>
          <AdminLayout><ManageProducts /></AdminLayout>
        </PrivateRoute>
      } />
      <Route path="/admin/markets" element={
        <PrivateRoute requireAdmin>
          <AdminLayout><ManageMarkets /></AdminLayout>
        </PrivateRoute>
      } />
      <Route path="/admin/prices" element={
        <PrivateRoute requireAdmin>
          <AdminLayout><ManagePrices /></AdminLayout>
        </PrivateRoute>
      } />

      {/* User Routes - Use Public Layout */}
      <Route path="/" element={<PrivateRoute><PublicLayout><Home /></PublicLayout></PrivateRoute>} />
      <Route path="/explore" element={<PrivateRoute><PublicLayout><Explore /></PublicLayout></PrivateRoute>} />
      <Route path="/scan" element={<PrivateRoute><PublicLayout><Scan /></PublicLayout></PrivateRoute>} />
      <Route path="/product/:id" element={<PrivateRoute><PublicLayout><ProductDetails /></PublicLayout></PrivateRoute>} />
      <Route path="/market/:id" element={<PrivateRoute><PublicLayout><MarketDetails /></PublicLayout></PrivateRoute>} />
      <Route path="/profile" element={<PrivateRoute><PublicLayout><Profile /></PublicLayout></PrivateRoute>} />

      {/* Fallback */}
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <HashRouter>
        <AppContent />
      </HashRouter>
    </AuthProvider>
  );
};

// Loader local para evitar erro de referência se não importado do lucide
const Loader2 = ({ className, size }: { className?: string, size?: number }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    width={size || 24} 
    height={size || 24} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M21 12a9 9 0 1 1-6.219-8.56" />
  </svg>
);

export default App;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Store, ShoppingBag, ChevronRight, Search, Tag } from 'lucide-react';
import { DB } from '../services/db';
import { Market, Product } from '../types';

export const Explore: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'mercados' | 'produtos'>('mercados');
  const [markets, setMarkets] = useState<Market[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const loadData = async () => {
      try {
        const [m, p] = await Promise.all([
          DB.getMarkets(),
          // Passa 'true' para filtrar apenas produtos ativos
          DB.getProducts(undefined, undefined, true)
        ]);
        setMarkets(m);
        setProducts(p);
      } catch (err) {
        console.error("Erro ao carregar dados de exploração:", err);
      }
    };
    loadData();
  }, []);

  const filteredMarkets = markets.filter(m => m.nome.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredProducts = products.filter(p => p.nome.toLowerCase().includes(searchTerm.toLowerCase()));

  // Agrupar produtos por categoria para a aba de produtos
  const categories = Array.from(new Set(products.map(p => p.categoria)));

  return (
    <div className="min-h-screen bg-slate-50">
      {/* Header Fixo da Página */}
      <div className="bg-white px-4 pt-6 pb-2 sticky top-0 z-30 shadow-sm md:static md:shadow-none">
        <h1 className="text-2xl font-extrabold text-gray-900 mb-4">Explorar</h1>

        {/* Busca */}
        <div className="relative mb-6">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder={activeTab === 'mercados' ? "Buscar mercados..." : "Buscar produtos..."}
            className="w-full pl-10 pr-4 py-3 bg-gray-100 border-none rounded-xl text-sm focus:ring-2 focus:ring-emerald-500 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {/* Custom Tabs (Mobile-Friendly) */}
        <div className="flex bg-gray-100 p-1 rounded-xl">
          <button 
            onClick={() => setActiveTab('mercados')}
            className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'mercados' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-500'}`}
          >
            Mercados
          </button>
          <button 
            onClick={() => setActiveTab('produtos')}
            className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'produtos' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-500'}`}
          >
            Produtos
          </button>
        </div>
      </div>

      <div className="p-4 max-w-7xl mx-auto">
        {activeTab === 'mercados' ? (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredMarkets.length > 0 ? filteredMarkets.map(market => (
              <Link to={`/market/${market.id}`} key={market.id} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex items-center justify-between group active:scale-[0.98] transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center">
                    <Store size={24} />
                  </div>
                  <div>
                    <h3 className="font-bold text-gray-800">{market.nome}</h3>
                    <p className="text-xs text-gray-400">Clique para ver ofertas</p>
                  </div>
                </div>
                <ChevronRight className="text-gray-300 group-hover:text-emerald-500 transition-colors" />
              </Link>
            )) : (
              <div className="col-span-full py-10 text-center text-gray-400">Nenhum mercado encontrado.</div>
            )}
          </div>
        ) : (
          <div className="space-y-8">
            {categories.map(category => {
              const categoryProducts = filteredProducts.filter(p => p.categoria === category);
              if (categoryProducts.length === 0) return null;

              return (
                <div key={category}>
                  <div className="flex items-center gap-2 mb-4">
                    <Tag size={16} className="text-emerald-500" />
                    <h2 className="font-bold text-gray-700 uppercase tracking-wider text-xs">{category}</h2>
                  </div>
                  <div className="grid gap-3">
